/// A tristate classification of whether an expression has side effects.
///
/// Merging is monotonic: [`SideEffect::Present`] dominates [`SideEffect::Possible`],
/// which in turn dominates [`SideEffect::Absent`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SideEffect {
    /// The expression is definitely side-effect-free.
    Absent,
    /// The expression may have side effects (e.g. an f-string interpolation may
    /// invoke `__format__` or `__str__`).
    Possible,
    /// The expression is assumed to have definite side effects (e.g. a walrus
    /// operator or a function call).
    Present,
}

impl SideEffect {
    /// Returns `true` only for [`SideEffect::Present`].
    pub const fn is_present(self) -> bool {
        matches!(self, SideEffect::Present)
    }

    /// Returns `true` only for [`SideEffect::Absent`].
    pub const fn is_absent(self) -> bool {
        matches!(self, SideEffect::Absent)
    }

    /// Combines two [`SideEffect`] values, keeping the more severe of the two.
    ///
    /// [`SideEffect::Present`] wins over [`SideEffect::Possible`], which wins over
    /// [`SideEffect::Absent`].
    #[must_use]
    pub fn merge(self, other: Self) -> Self {
        match (self, other) {
            (SideEffect::Present, _) | (_, SideEffect::Present) => SideEffect::Present,
            (SideEffect::Possible, _) | (_, SideEffect::Possible) => SideEffect::Possible,
            (SideEffect::Absent, SideEffect::Absent) => SideEffect::Absent,
        }
    }
}

/// Traverse an `Expr` and return the combined [`SideEffect`] of all sub-expressions.
///
/// An f-string that interpolates a non-literal expression is classified as
/// [`SideEffect::Possible`], since evaluating it may invoke `__format__` or `__str__`.
/// Named expressions (the walrus operator), function calls, subscripts, `await`,
/// `yield`, and comprehensions are classified as [`SideEffect::Present`]. All other
/// expressions are classified as [`SideEffect::Absent`].
///
/// Accepts a closure that determines whether a given name (e.g., `"list"`) is a Python builtin.
///
/// The traversal short-circuits and returns [`SideEffect::Present`] as soon as a
/// [`SideEffect::Present`] sub-expression is found.
pub fn side_effect<F>(expr: &Expr, is_builtin: F) -> SideEffect
where
    F: Fn(&str) -> bool,
{
    let mut effect = SideEffect::Absent;
    any_over_expr(expr, |expr| {
        effect = effect.merge(node_side_effect(expr, &is_builtin));
        effect.is_present()
    });
    effect
}

/// Return the [`SideEffect`] of a single expression node, without recursing into its
/// children (recursion is handled by [`side_effect`] via [`any_over_expr`]).
fn node_side_effect<F>(expr: &Expr, is_builtin: &F) -> SideEffect
where
    F: Fn(&str) -> bool,
{
    // Named expressions (the walrus operator) rebind a variable and thus always have a
    // side effect.
    if matches!(expr, Expr::Named(_)) {
